# C-style pseudocode
# pragma omp parallel for reduction(+:sum)
# for (i = 0; i < n; i++)
#     sum += a[i] * b[i];
# The loop iterations are split across threads;
# the reduction clause safely combines partial sums.

# CUDA C pseudocode for c = a + b
# __global__ void add(float* a, float* b, float* c, int n){
#   int i = blockIdx.x * blockDim.x + threadIdx.x;
#   if (i < n) c[i] = a[i] + b[i];
# }
# launch: add<<<(n+255)/256, 256>>>(a, b, c, n);

def amdahl(p, n):
    return 1.0 / ((1.0 - p) + p / n)

for n in (2, 8, 64, 1024):
    print(n, round(amdahl(0.95, n), 2))
# 2 -> 1.9, 8 -> 6.1, 64 -> 15.4, 1024 -> 19.7
# converging on the 20x ceiling

def gustafson(s, n):
    return s + n * (1.0 - s)

for n in (8, 64, 1024):
    print(n, round(gustafson(0.05, n), 1))
# 8 -> 7.7, 64 -> 61.0, 1024 -> 972.9
# near-linear scaled speedup
